llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Uridine, a polar ribonucleoside, had an absolute oral bioavailability of only 5.8% in a healthy volunteer; the query is a similarly polar xanthine ribonucleoside, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "NHC, a modified ribonucleoside with an additional polar substituent, has poor human oral bioavailability; the query's extra N-ribosylamine linker and xanthine base create comparable polarity and permeability liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Levovirin has less than 10% human oral bioavailability due to very low permeability; the query's highly polar xanthine/N-ribosylamine structure is expected to have similarly poor permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "5-Fluorouridine, a ribonucleoside with a halogenated uracil, has about 25% oral bioavailability; the halogen increases lipophilicity, so this high-F result transfers only weakly to the more polar query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C49"],
      "claim": "Fludarabine, a purine nucleoside, has about 55% oral bioavailability, suggesting some purine nucleosides can be well absorbed; however, the query's xanthine base is more polar and lacks the adenine amino group.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly polar xanthine ribonucleoside with an extra N-ribosylamine linker, likely conferring poor permeability and acid lability. Closest polar ribonucleoside analogues (uridine, NHC, levovirin) show low oral bioavailability, while high-F analogues are more lipophilic or have transporter-favorable bases. Therefore F is predicted below 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query or a close xanthine N-ribosylamine analogue.",
    "Unknown acid stability of the N-ribosylamine glycosidic linkage under oral conditions.",
    "Unknown affinity for intestinal nucleoside transporters (CNT/ENT) and extent of first-pass metabolism."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

